static void xlPAppendStmt(XL_AstNode* pList, XL_AstNode* pStmt)
{
	if ( (pList == NULL) || (pStmt == NULL) ) {
		return;
	}
	if ( pStmt->eKind == XL_AST_LIST ) {
		xlAstAppendChildren(pList, pStmt);
		return;
	}
	xlAstAppendChild(pList, pStmt);
}
